import{at as e,it as t,t as n,yt as r}from"./chunks/framework.DB37bP8J.js";var i=JSON.parse(`{"title":"Data","description":"Learn the four data representations (API, wire, cache, presentation) WarpDrive asks you to align and why JSON:API is the recommended wire and cache format.","frontmatter":{"description":"Learn the four data representations (API, wire, cache, presentation) WarpDrive asks you to align and why JSON:API is the recommended wire and cache format.","draft":true},"headers":[],"relativePath":"guides/the-manual/data.md","filePath":"guides/the-manual/data.md"}`),a={name:`guides/the-manual/data.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to “Data”">​</a></h1><p>In every application data can take on many different representations:</p><ul><li>the API format (what your backend understands)</li><li>the wire format (what your backend sends you)</li><li>the cache format (what your frontend deserializes the wire format into)</li><li>the presentation format (what your frontend transforms the cache format into for utility)</li></ul><p>As much as possible, WarpDrive encourages aligning <em>at-least</em> the first three of these four formats. Aligning formats reduces the mental complexity required to understand the flow of data through your application, making it easier to debug, and reduces the computation necessary at each layer, making your application faster.</p><p>Misalignment tends to occur when API and Application developers don&#39;t work together to understand requirements, or when the format in use is &quot;lossy&quot; (unable to accurately convey the full scope of information being serialized).</p><p>We encourage the use of <a href="https://jsonapi.org/" target="_blank" rel="noreferrer">JSON:API</a> as the wire and cache format because unlike most other formats in use today it encodes information about your data in a near-lossless and easily-cacheable manner.</p><p>For the presentation format, we encourage applications to limit the amount of manual transformation done. Applications should wherever possible align the interfaces of the data components expect to the shape of the data available, rather than transforming data to fit into the component. This said, WarpDrive offers powerful schema-defined transformation and derivation capabilities built-in to the reactivity layer for presenting data from the cache. Handling transformation universally via schema enables apps to align to component interfaces where needed in a safer, more performant manner.</p><p>We&#39;ll explore these capabilities later on in the manual in the sections on Presentation and Schemas. But first, lets take some time to look at some key concepts surrounding the wire and cache format.</p><h3 id="structureddocuments" tabindex="-1">StructuredDocuments <a class="header-anchor" href="#structureddocuments" aria-label="Permalink to “StructuredDocuments”">​</a></h3><h3 id="resourcedocuments" tabindex="-1">ResourceDocuments <a class="header-anchor" href="#resourcedocuments" aria-label="Permalink to “ResourceDocuments”">​</a></h3><h3 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to “Resources”">​</a></h3><h3 id="cachekeys" tabindex="-1">CacheKeys <a class="header-anchor" href="#cachekeys" aria-label="Permalink to “CacheKeys”">​</a></h3><h3 id="membership" tabindex="-1">Membership <a class="header-anchor" href="#membership" aria-label="Permalink to “Membership”">​</a></h3><h3 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to “Fields”">​</a></h3>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};